// reproduce.js (place at your project root alongside lighthouse-cli)
// 
// This script calls the CLI runner directly with a URL that lacks a protocol,
// triggering a fatal INVALID_URL error and demonstrating the un-localized template ID.

const path = require('path');
// Adjust this path if your working directory differs
const runLighthouse = require(path.join(__dirname, 'lighthouse-cli', 'run.js'));

(async () => {
  try {
    // Intentionally omit 'http://' or 'https://' to trigger INVALID_URL
    await runLighthouse({
      _: ['www.example.com'],  // first argument is the URL
      view: true,               // `--view` flag
    });
  } catch (err) {
    // At this point `err.friendlyMessage` is still the raw template reference
    console.error('friendlyMessage:', err.friendlyMessage);
    console.error('err.message:', err.message);
  }
})();
